// Category A — behavior-only context wrapper. No DOM/look of its own (the same kind as FileTrigger).
// Wraps SearchField (or TextField) + Menu/ListBox/GridList to provide live filtering
// — command-palette-style patterns ("⌘K" search + execute). Because children connect automatically
// through context, this component itself has nothing to render.
import { Autocomplete as AriaAutocomplete } from "react-aria-components";
import type { AutocompleteProps as AriaAutocompleteProps } from "react-aria-components";
import "./Autocomplete.css";

export interface AutocompleteProps extends AriaAutocompleteProps {}

export function Autocomplete(props: AutocompleteProps) {
  return <AriaAutocomplete {...props} />;
}

/* RAC's Autocomplete renders no wrapper DOM — it's a pure context provider around
   its children (a SearchField/Input paired with a Menu/ListBox/GridList). Nothing
   to style here; the look lives entirely in the child components. */
